  --aif-border-strong: #1f1e1d4d;
  --aif-border-focus: #b9573a;
  --aif-accent: #b9573a;
  --aif-accent-rgb: 185, 87, 58;
  --aif-accent-hover: #a64a30;
  --aif-accent-soft: #f6e9e2;
  --aif-on-accent: #fffdfa;
  --aif-danger: #b84946;
  --aif-danger-rgb: 184, 73, 70;
  --aif-warning: #a66b31;
  --aif-success: #4b7c5a;
