	--shadow-active-tab: 0 10px 24px color-mix(in srgb, var(--aif-accent) 18%, transparent);
	--window-controls-width: 126px;
	--top-bars-height: 70px;
position:absolute;inset:0;z-index:1;background:var(--workspace-bg);color:var(--chrome-text);font-family:"PDF AI Crimson Text","PDF AI Source Han Serif SC","Noto Serif SC","Microsoft YaHei UI",serif;font-size:12px;font-weight:400;line-height:normal}.home-view[hidden]{display:none}html[data-theme="dark"] .home-view{  --aif-bg: #262624;
