.secondary-action-button {
	width: 100%;
	height: 32px;
	border: 1px solid var(--chrome-border);
	border-radius: 9px;
	background: color-mix(in srgb, var(--chrome-active) 82%, var(--panel-bg));
	color: var(--chrome-text);
	cursor: pointer;
}

.primary-action-button,
.secondary-action-button {
	display: inline-flex;
	align-items: center;
	justify-content: center;
}

.home-content {
	height: 100%;
	padding: 44px 48px;
	display: flex;
	flex-direction: column;
	gap: 28px;
	overflow: auto;
	background: var(--workspace-bg);
}

.home-hero {
	max-width: 760px;
}

.home-brand-lockup {
	display: inline-flex;
	align-items: center;
	gap: 12px;
	margin-bottom: 14px;
}

.home-brand-mark {
	width: 36px;
	height: 34px;
	background: var(--chrome-accent);
	-webkit-mask: url("data:image/svg+xml;base64,") center / contain no-repeat;
	mask: url("data:image/svg+xml;base64,") center / contain no-repeat;
	flex: 0 0 auto;
}

.home-eyebrow {
	font-size: 12px;
	line-height: 1;
	letter-spacing: 0.08em;
	text-transform: uppercase;
	color: var(--chrome-accent);
	margin: 0;
}

.home-hero h1 {
	margin: 0 0 12px;
	font-size: 32px;
	line-height: 1.1;
	font-weight: 650;
}

.home-hero p {
	margin: 0;
	max-width: 620px;
	font-size: 14px;
	line-height: 1.7;
	color: var(--chrome-muted);
}

.home-recent-section {
	display: flex;
	flex-direction: column;
	gap: 14px;
	max-width: 980px;
	padding: 18px 20px 20px;
	border: 1px solid var(--chrome-border);
	border-radius: 16px;
	background: color-mix(in srgb, var(--workspace-bg) 92%, var(--chrome-bg));
	box-shadow: var(--chrome-shadow);
}

html[data-theme="dark"] .home-recent-section {
	box-shadow: var(--chrome-shadow-strong);
}

.home-section-header {
	display: flex;
	align-items: flex-start;
	justify-content: flex-start;
	gap: 18px;
	flex-wrap: wrap;
}

.home-section-header h2 {
	margin: 0;
	font-size: 16px;
	font-weight: 640;
}

.home-section-meta {
	font-size: 12px;
	color: var(--chrome-muted);
}

.home-recent-list {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 10px;
}

.home-recent-empty {
	padding: 16px 4px 4px;
	font-size: 13px;
	line-height: 1.6;
	color: var(--chrome-muted);
}

.home-recent-item {
	position: relative;
	width: 100%;
	padding: 14px 14px 14px 14px;
	border: 1px solid var(--chrome-border);
	border-radius: 12px;
	background: color-mix(in srgb, var(--chrome-active) 80%, var(--workspace-bg));
	color: var(--chrome-text);
	text-align: left;
	cursor: pointer;
	display: grid;
	grid-template-columns: minmax(0, 1fr) 92px;
	grid-template-rows: auto auto;
	gap: 12px;
	align-items: start;
	min-height: 148px;
}

.home-recent-item:hover {
	border-color: var(--chrome-border-strong);
	background: var(--chrome-active);
}

.home-recent-title {
	font-size: 14px;
	font-weight: 620;
	line-height: 1.45;
	word-break: break-word;
	display: -webkit-box;
	-webkit-line-clamp: 3;
	-webkit-box-orient: vertical;
	overflow: hidden;
}

.home-recent-content {
	grid-column: 1;
	grid-row: 1;
	min-width: 0;
	display: flex;
	flex-direction: column;
	gap: 6px;
}

.home-recent-path,
.home-recent-date {
	font-size: 12px;
	line-height: 1.5;
	color: var(--chrome-muted);
}

.home-recent-path {
	min-width: 0;
	padding: 0;
	border: 0;
	background: transparent;
	text-align: left;
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
	cursor: pointer;
}

.home-recent-path:hover {
	color: var(--chrome-accent);
}

html[data-theme="dark"] .home-recent-path:hover {
	color: var(--chrome-accent);
}

.home-recent-date {
	white-space: nowrap;
	margin-top: auto;
}

.home-recent-thumbnail {
	grid-column: 2;
	grid-row: 1;
	width: 92px;
	height: 120px;
	border-radius: 8px;
	border: 1px solid var(--chrome-border);
	background: var(--panel-bg);
	overflow: hidden;
	display: flex;
	align-items: center;
	justify-content: center;
	flex: 0 0 auto;
}

.home-recent-thumbnail-fallback {
	padding: 8px;
	background: color-mix(in srgb, var(--chrome-accent) 8%, var(--panel-bg));
}

html[data-theme="dark"] .home-recent-thumbnail-fallback {
	background: var(--panel-bg);
}

.home-recent-thumbnail img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	display: block;
}

.home-recent-thumbnail-paper {
	width: 100%;
	height: 100%;
	border-radius: 8px;
	background: var(--chrome-active);
	border: 1px solid color-mix(in srgb, var(--chrome-accent) 22%, transparent);
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82);
	display: flex;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	gap: 10px;
}

html[data-theme="dark"] .home-recent-thumbnail-paper {
	background: var(--chrome-active);
	border-color: rgba(122, 169, 255, 0.22);
	box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05);
}

.home-recent-thumbnail-glyph {
	font-size: 28px;
	font-weight: 700;
	line-height: 1;
	color: #5a6d91;
}

html[data-theme="dark"] .home-recent-thumbnail-glyph {
	color: #dce5fb;
}

.home-recent-thumbnail-badge {
	padding: 3px 8px;
	border-radius: 999px;
	background: color-mix(in srgb, var(--chrome-accent) 12%, transparent);
	color: color-mix(in srgb, var(--chrome-accent) 82%, var(--chrome-text));
	font-size: 11px;
	font-weight: 700;
	letter-spacing: 0.04em;
}

html[data-theme="dark"] .home-recent-thumbnail-badge {
	background: rgba(122, 169, 255, 0.16);
	color: #cfe0ff;
}

.home-recent-actions {
	grid-column: 1 / -1;
	grid-row: 2;
	display: inline-flex;
	align-items: center;
	justify-content: flex-end;
	gap: 6px;
	width: 100%;
	margin-top: 2px;
	z-index: 2;
}

.home-recent-menu {
	position: relative;
}

.home-recent-menu summary {
	list-style: none;
}

.home-recent-menu summary::-webkit-details-marker {
	display: none;
}

.home-recent-menu-button,
.home-recent-remove {
	width: 24px;
	height: 24px;
	padding: 0;
	border: 0;
	border-radius: 999px;
	background: color-mix(in srgb, var(--chrome-bg) 80%, transparent);
	color: var(--chrome-muted);
	cursor: pointer;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	font-size: 14px;
	line-height: 1;
}

.home-recent-menu-button:hover,
.home-recent-remove:hover {
	background: var(--chrome-hover);
	color: var(--chrome-text);
}

.home-recent-menu[open] .home-recent-menu-button {
	background: var(--chrome-hover);
	color: var(--chrome-text);
}

.home-recent-menu-popup {
	position: absolute;
	right: 0;
	bottom: calc(100% + 6px);
	z-index: 8;
	min-width: 132px;
	padding: 6px;
	border: 1px solid var(--chrome-border);
	border-radius: 10px;
	background: var(--workspace-bg);
	box-shadow: 0 12px 28px rgba(0, 0, 0, 0.16);
	display: flex;
	flex-direction: column;
	gap: 2px;
}

html[data-theme="dark"] .home-recent-menu-popup {
	box-shadow: 0 14px 32px rgba(0, 0, 0, 0.34);
}

.home-recent-menu-popup button {
	padding: 7px 10px;
	border: 0;
	border-radius: 8px;
	background: transparent;
	color: var(--chrome-text);
	text-align: left;
	cursor: pointer;
	font-size: 12px;
}

.home-recent-menu-popup button:hover {
	background: var(--chrome-hover);
}

.secondary-action-button.home-workspace-create {
	width: auto;
	min-width: 132px;
	height: 34px;
	flex: 0 0 auto;
	padding: 0 18px;
	border-radius: 999px;
	white-space: nowrap;
}

.home-recent-section {
	width: 100%;
	max-width: none;
}

.home-recent-list {
	display: flex;
	flex-direction: column;
	gap: 18px;
}

.home-workspace-column {
	width: 100%;
	padding: 0;
	border-top: 1px solid color-mix(in srgb, var(--chrome-border) 76%, transparent);
}

.home-workspace-column:first-child {
	border-top: 0;
}

.home-workspace-container {
	position: relative;
	width: 100%;
	max-width: 100%;
	padding: 18px 20px 22px;
	border: 1px solid color-mix(in srgb, var(--chrome-border) 72%, transparent);
	border-radius: 18px;
	background: color-mix(in srgb, var(--workspace-bg) 82%, var(--chrome-active));
	box-shadow: inset 0 1px 0 color-mix(in srgb, #ffffff 50%, transparent);
	transition: border-color 140ms ease, background-color 140ms ease, box-shadow 140ms ease;
}

.home-workspace-column.is-pdf-drop-target .home-workspace-container {
	border-color: color-mix(in srgb, var(--chrome-accent) 72%, var(--chrome-border));
	background: color-mix(in srgb, var(--workspace-bg) 78%, var(--chrome-accent));
	box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--chrome-accent) 30%, transparent), 0 0 0 3px color-mix(in srgb, var(--chrome-accent) 12%, transparent);
	cursor: copy;
}

.home-workspace-column.is-pdf-drop-target .home-workspace-header,
.home-workspace-column.is-pdf-drop-target .home-workspace-books {
	opacity: 0.28;
}

.home-workspace-drop-indicator {
	position: absolute;
	inset: 10px;
	z-index: 12;
	display: flex;
	align-items: center;
	justify-content: center;
	padding: 18px;
	border: 1px dashed color-mix(in srgb, var(--chrome-accent) 72%, var(--chrome-border));
	border-radius: 12px;
	color: color-mix(in srgb, var(--chrome-accent) 86%, var(--chrome-text));
	font-size: 14px;
	font-weight: 720;
	letter-spacing: 0;
	line-height: 1.4;
	text-align: center;
	pointer-events: none;
}

.home-workspace-drop-indicator[hidden] {
	display: none;
}

.home-workspace-column.is-pdf-drop-importing .home-workspace-container {
	cursor: wait;
}

.home-workspace-column.active .home-workspace-container {
	border-color: color-mix(in srgb, var(--chrome-accent) 24%, var(--chrome-border));
	background: color-mix(in srgb, var(--workspace-bg) 84%, var(--chrome-active));
}

.home-workspace-column.active.is-pdf-drop-target .home-workspace-container {
	border-color: color-mix(in srgb, var(--chrome-accent) 72%, var(--chrome-border));
	background: color-mix(in srgb, var(--workspace-bg) 78%, var(--chrome-accent));
}

.home-workspace-header {
	display: flex;
	align-items: stretch;
	justify-content: flex-start;
	margin-bottom: 18px;
}

.home-workspace-heading {
	width: 100%;
	flex: 0 0 auto;
	min-width: 0;
	display: flex;
	flex-direction: column;
	gap: 5px;
}

.home-workspace-title-row {
	display: flex;
	align-items: center;
	gap: 10px;
	min-width: 0;
	width: 100%;
}

.home-workspace-title-row h3 {
	margin: 0;
	flex: 1 1 auto;
	min-width: 0;
	font-size: 17px;
	font-weight: 720;
	letter-spacing: -0.02em;
	color: var(--chrome-text);
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.home-workspace-pill {
	flex: 0 0 auto;
	padding: 4px 9px;
	border-radius: 999px;
	background: color-mix(in srgb, var(--chrome-accent) 13%, transparent);
	color: color-mix(in srgb, var(--chrome-accent) 86%, var(--chrome-text));
	font-size: 11px;
	font-weight: 680;
}

.home-workspace-root {
	max-width: 100%;
	font-size: 12px;
	color: var(--chrome-muted);
	overflow: hidden;
	text-overflow: ellipsis;
	white-space: nowrap;
}

.home-workspace-actions {
	flex: 0 0 auto;
	display: flex;
	align-items: center;
	justify-content: flex-end;
	gap: 6px;
	flex-wrap: nowrap;
	max-width: max-content;
	margin-left: auto;
	padding: 0;
	border: 0;
	border-radius: 0;
	background: transparent;
	box-shadow: none;
}

.home-workspace-actions .secondary-action-button {
	width: auto;
	min-width: 0;
	height: 28px;
	padding: 0 10px;
	border-radius: 999px;
	font-size: 12px;
	white-space: nowrap;
}

.home-workspace-actions .home-workspace-delete {
	border-color: color-mix(in srgb, #c94f3d 34%, var(--chrome-border));
	color: color-mix(in srgb, #c94f3d 84%, var(--chrome-text));
}

.home-workspace-actions .home-workspace-switch.is-current {
	opacity: 0.5;
	cursor: default;
	pointer-events: none;
}

.home-workspace-books {
	display: flex;
	align-items: flex-start;
	align-content: flex-start;
	flex-wrap: wrap;
	gap: 18px 18px;
	width: 100%;
}

.perspective-book-card {
	position: relative;
	--book-bg: #2d5b8a;
	--book-fg: #ffffff;
	--book-edge: #173753;
	--book-page: #ffffff;
	--book-page-line: #ded7ca;
	width: 198px;
	height: 210px;
	min-height: 0;
	padding: 0;
	border: 0;
	background: transparent;
	box-shadow: none;
	display: block;
	cursor: default;
	overflow: visible;
}

.perspective-book-card:hover {
	background: transparent;
	border-color: transparent;
}

/* Official Spell UI component supplies the 3D geometry and animation. */
.spell-perspective-book { position:relative;z-index:1;width:min-content;height:min-content;margin:8px 46px 8px 4px;cursor:pointer; }
.spell-perspective-book:focus-visible {outline:3px solid color-mix(in srgb,var(--chrome-accent) 45%,transparent);outline-offset:6px;border-radius:10px}
.workspace-book-cover {background:var(--book-bg);color:var(--book-fg);box-sizing:border-box}
.spell-perspective-book [style*="translateZ(-25px)"] {background:var(--book-bg);border:1px solid #00000014}
.spell-perspective-book [style*="rotateY(90deg)"] {background:#ffffff;box-shadow:inset 1px 0 #dedede,inset -1px 0 #ededed}
.spell-perspective-book:focus-visible > .group > div {transform:rotateY(-20deg);scale:1.066;translate:-4px}
.spell-perspective-book-content {
	position: relative;
	z-index: 1;
	height: 100%;
	display: flex;
	flex-direction: column;
	justify-content: space-between;
	gap: 8px;
	padding-left: 4px;
}

.spell-perspective-book-title {
	margin-top: 0;
	font-size: 11.5px;
	font-weight: 760;
	line-height: 1.25;
	letter-spacing: -0.02em;
	text-wrap: balance;
	user-select: none;
	display: -webkit-box;
	-webkit-line-clamp: 8;
	min-height:0;
	-webkit-box-orient: vertical;
	overflow: hidden;
}

.spell-perspective-book-author {
	margin-top:auto;
	flex-shrink:0;
	font-family: Georgia, "Times New Roman", serif;
	font-size: 11px;
	font-weight: 620;
	line-height: 1.16;
	opacity: 0.92;
	user-select: none;
	display: -webkit-box;
	-webkit-line-clamp: 2;
	-webkit-box-orient: vertical;
	overflow: hidden;
}

.perspective-book-card .home-recent-actions {
	position: absolute;
	left: 164px;
	top: 13px;
	width: 30px;
	margin: 0;
	display: flex;
	align-items: center;
	justify-content: center;
	flex-direction: column;
	gap: 8px;
	z-index: 4;
	padding: 0;
	border: 0;
	border-radius: 0;
	background: transparent;
	box-shadow: none;
	backdrop-filter: none;
	opacity: 0.48;
	transform: none;
	transition: opacity 140ms ease, transform 140ms ease;
}

.perspective-book-card:hover .home-recent-actions,
.perspective-book-card:focus-within .home-recent-actions {
	opacity: 0.82;
	transform: translateX(1px);
}

.perspective-book-card .home-recent-menu-popup {
	left: auto;
	right: 0;
	top: calc(100% + 8px);
	bottom: auto;
	transform: none;
}

.perspective-book-card .home-recent-menu-button,
.perspective-book-card .home-recent-remove {
	width: 30px;
	height: 30px;
	background: color-mix(in srgb, var(--workspace-bg) 80%, transparent);
	box-shadow: 0 8px 18px rgba(25, 21, 16, 0.06);
	backdrop-filter: blur(8px);
	font-weight: 650;
}

.perspective-book-card .home-recent-menu-button:hover,
.perspective-book-card .home-recent-remove:hover,
.perspective-book-card .home-recent-menu[open] .home-recent-menu-button {
	background: color-mix(in srgb, var(--chrome-accent) 12%, var(--chrome-hover));
}

@media (max-width: 1320px) {
